import static org.junit.Assert.*;

/**
 * Unit tests for MutableDateTime.addWeeks
 */
public class MutableDateTime_addWeeks_TriageGen0Test {

    @Test
    public void testAddWeeksPositive() {
        // Initialize with a known date: 2023-01-01 (Sunday)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        int weeksToAdd = 2;

        dt.addWeeks(weeksToAdd);

        // 2023-01-01 + 14 days = 2023-01-15
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeksNegative() {
        // Initialize with a known date: 2023-01-15
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 0, 0, 0, 0);
        int weeksToAdd = -1;

        dt.addWeeks(weeksToAdd);

        // 2023-01-15 - 7 days = 2023-01-08
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(8, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeksZero() {
        // Initialize with a known date
        MutableDateTime dt = new MutableDateTime(2023, 5, 20, 10, 30, 0, 0);
        int weeksToAdd = 0;

        dt.addWeeks(weeksToAdd);

        // Date should remain unchanged
        assertEquals(2023, dt.getYear());
        assertEquals(5, dt.getMonthOfYear());
        assertEquals(20, dt.getDayOfMonth());
        assertEquals(10, dt.getHourOfDay());
        assertEquals(30, dt.getMinuteOfHour());
    }

    @Test
    public void testAddWeeksCrossingYearBoundary() {
        // Initialize at the end of the year
        MutableDateTime dt = new MutableDateTime(2023, 12, 25, 0, 0, 0, 0);
        int weeksToAdd = 2;

        dt.addWeeks(weeksToAdd);

        // 2023-12-25 + 14 days = 2024-01-08
        assertEquals(2024, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(8, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeksCrossingLeapYear() {
        // February 2024 is a leap year
        MutableDateTime dt = new MutableDateTime(2024, 2, 20, 0, 0, 0, 0);
        int weeksToAdd = 2;

        dt.addWeeks(weeksToAdd);

        // 2024-02-20 + 14 days = 2024-03-05 (since Feb has 29 days)
        assertEquals(2024, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(5, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeksLargeValue() {
        MutableDateTime dt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        int weeksToAdd = 5200; // 100 years approximately

        dt.addWeeks(weeksToAdd);

        // Check that it didn't crash and moved forward significantly
        assertTrue(dt.getYear() >= 2100);
    }
}
